commands.command:
set -eu
sudo -u postgres -- psql -X -v ON_ERROR_STOP=1 --dbname=helpdesk -P pager=off <<'SQL'
SELECT setval(
  pg_get_serial_sequence('public.tickets', 'id'),
  COALESCE((SELECT max(id) FROM public.tickets), 1),
  EXISTS (SELECT 1 FROM public.tickets)
) AS repaired_sequence_value;
BEGIN;
INSERT INTO public.tickets(subject) VALUES ('sequence verification') RETURNING id AS allocated_test_id;
ROLLBACK;
SELECT id, subject FROM public.tickets ORDER BY id;
SELECT count(*) AS ticket_count,
       min(id) AS min_id,
       max(id) AS max_id,
       count(DISTINCT id) AS distinct_ids
FROM public.tickets;
SELECT last_value, is_called FROM public.tickets_id_seq;
SQL
sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql
stat -c '%n size=%s mode=%a owner=%U:%G mtime=%y' /srv/legacy2/postgresql-sequence-repair/tickets.sql

set -eu
printf 'boot_id='; cat /proc/sys/kernel/random/boot_id
printf 'os='; . /etc/os-release; printf '%s %s\n' "$PRETTY_NAME" "$(uname -r)"
printf 'selinux='; getenforce
printf 'postgresql_enabled='; systemctl is-enabled postgresql
printf 'postgresql_active='; systemctl is-active postgresql
sudo -u postgres -- pg_isready
sudo -u postgres -- psql -X -v ON_ERROR_STOP=1 --dbname=helpdesk -P pager=off <<'SQL'
SELECT id, subject FROM public.tickets ORDER BY id;
SELECT count(*) AS ticket_count, max(id) AS imported_max, count(DISTINCT id) AS distinct_ids FROM public.tickets;
SELECT last_value, is_called FROM public.tickets_id_seq;
BEGIN;
INSERT INTO public.tickets(subject) VALUES ('post-restart sequence verification') RETURNING id AS allocated_post_restart_id;
ROLLBACK;
SELECT count(*) AS ticket_count_after_rollback, max(id) AS imported_max_after_rollback FROM public.tickets;
SELECT last_value, is_called FROM public.tickets_id_seq;
SQL
sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql
stat -c '%n size=%s mode=%a owner=%U:%G mtime=%y' /srv/legacy2/postgresql-sequence-repair/tickets.sql
